#!/usr/bin/env python3
"""Non-destructive arch196e E1 probe. No camera access, daemon changes or sudo."""
import base64, datetime, hashlib, json, os, pathlib, platform, shutil, subprocess, sys, tempfile, time, zipfile
SWIFT_SOURCE = 'import Foundation\nimport Vision\nimport ImageIO\nimport CoreML\n\nlet args = CommandLine.arguments\nif args.count != 4 { fputs("usage: probe image mode request\\n", stderr); exit(2) }\nlet mode = args[2], kind = args[3]\nlet request: VNImageBasedRequest = kind == "rectangles" ? VNDetectFaceRectanglesRequest() : VNDetectFaceLandmarksRequest()\nif mode == "cpu" {\n    if #available(macOS 14.0, *) {\n        do {\n            let stages = try request.supportedComputeStageDevices\n            guard !stages.isEmpty else { print("PROBE_RESULT mode=\\(mode) request=\\(kind) status=cpu-unavailable"); exit(3) }\n            for (stage, devices) in stages {\n                guard let cpu = devices.first(where: { if case .cpu = $0 { return true }; return false }) else {\n                    print("PROBE_RESULT mode=\\(mode) request=\\(kind) status=cpu-unavailable stage=\\(stage)"); exit(3)\n                }\n                request.setComputeDevice(cpu, for: stage)\n            }\n        } catch {\n            print("PROBE_RESULT mode=\\(mode) request=\\(kind) status=cpu-query-error error=\\(error)"); exit(3)\n        }\n    } else { request.usesCPUOnly = true }\n}\nlet started = ProcessInfo.processInfo.systemUptime\nprint("PROBE_START pid=\\(getpid()) mode=\\(mode) request=\\(kind)"); fflush(stdout)\ndo {\n    let handler = VNImageRequestHandler(url: URL(fileURLWithPath: args[1]), orientation: .up, options: [:])\n    try handler.perform([request])\n    print("PROBE_RESULT mode=\\(mode) request=\\(kind) status=returned seconds=\\(ProcessInfo.processInfo.systemUptime-started) observations=\\(request.results?.count ?? 0)")\n} catch {\n    print("PROBE_RESULT mode=\\(mode) request=\\(kind) status=error seconds=\\(ProcessInfo.processInfo.systemUptime-started) error=\\(error)"); exit(4)\n}\n'
IMAGE_B64 = ''
IMAGE_SHA256 = '43800f6b0a6140d41b86791969e6e06ae0e977f8a894e09337e613ad0d460c99'

def run_owned(args, timeout, output):
    started=time.monotonic()
    with output.open('wb') as stream:
        child=subprocess.Popen(args,stdout=stream,stderr=subprocess.STDOUT)
        try:
            code=child.wait(timeout=timeout)
            state='returned' if code==0 else 'error'
        except subprocess.TimeoutExpired:
            child.kill()
            try: child.wait(timeout=2)
            except subprocess.TimeoutExpired: pass
            code=None;state='timeout'
    return {'status':state,'exit':code,'seconds':round(time.monotonic()-started,3)}

def main():
    if platform.system()!='Darwin':
        print('This probe needs macOS. No changes made.');return 2
    # Do not quit or signal the application automatically.
    check=subprocess.run(['/usr/bin/pgrep','-ix','gor'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    if check.returncode==0:
        print('Quit gor first, then run this same command again. No process was changed.');return 2
    if check.returncode!=1:
        print('Cannot verify that gor is closed. No probe started.');return 2
    stamp=datetime.datetime.now().strftime('%y%m%d-%H%M%S-%f')
    root=pathlib.Path(tempfile.mkdtemp(prefix='gor-vision-e1-',dir='/tmp'));os.chmod(root,0o700)
    print('Evidence:',root,flush=True)
    (root/'probe.swift').write_text(SWIFT_SOURCE)
    image=base64.b64decode(IMAGE_B64);assert hashlib.sha256(image).hexdigest()==IMAGE_SHA256
    (root/'face.png').write_bytes(image)
    (root/'IMAGE-SOURCE.txt').write_text('NASA Eileen Collins image, no known copyright restrictions. Bundled from scikit-image v0.17.2 data/astronaut.png.\nhttps://github.com/scikit-image/scikit-image/blob/v0.17.2/skimage/data/__init__.py\nhttps://raw.githubusercontent.com/scikit-image/scikit-image/v0.17.2/skimage/data/astronaut.png\nSHA256 '+IMAGE_SHA256+'\n')
    result={'schema':1,'timestamp':datetime.datetime.now().astimezone().isoformat(),'gor_closed':True,'evidence':str(root),'commands':{},'probes':[]}
    commands=[('sw_vers',['/usr/bin/sw_vers'],10),('uptime',['/usr/bin/uptime'],10),('boot',['/usr/sbin/sysctl','kern.boottime'],10),('softwareupdate-history',['/usr/sbin/softwareupdate','--history'],30),('aned-errors',['/usr/bin/log','show','--last','2d','--style','compact','--predicate','process == "aned" AND (messageType == error OR messageType == fault)'],30)]
    for name,args,timeout in commands:
        try: result['commands'][name]=run_owned(args,timeout,root/(name+'.txt'))
        except OSError as error: result['commands'][name]={'status':'unavailable','error':str(error)}
    # Compilation time is distinct from each 10s Vision run.
    result['compile']=run_owned(['/usr/bin/xcrun','swiftc',str(root/'probe.swift'),'-o',str(root/'probe')],120,root/'compile.txt')
    if result['compile']['status']=='returned':
        for mode in ('default','cpu'):
            for kind in ('rectangles','landmarks'):
                name=mode+'-'+kind
                row=run_owned([str(root/'probe'),str(root/'face.png'),mode,kind],10,root/(name+'.txt'))
                row.update(mode=mode,request=kind);result['probes'].append(row)
                print(name,row['status'],str(row['seconds'])+'s',flush=True)
    statuses=[x['status'] for x in result['probes']]
    if 'timeout' in statuses: verdict='standalone-Vision-timeout-with-gor-closed; system/Vision path implicated; aned cause still requires restart comparison'
    elif len(statuses)==4 and all(x=='returned' for x in statuses): verdict='standalone-Vision-returned; current system-wide hang not reproduced; inspect camera effects next'
    else: verdict='probe-inconclusive; inspect compile/device/error receipts'
    result['result']=verdict
    aned_text=(root/'aned-errors.txt').read_text(errors='replace')
    result['aned_error_fault_lines']=sum(1 for line in aned_text.splitlines() if 'aned' in line and ('Error' in line or 'Fault' in line))
    result['boot']=(root/'boot.txt').read_text(errors='replace').strip()
    summary='E1 '+result['timestamp']+' | '+(root/'sw_vers.txt').read_text(errors='replace').replace('\n','; ').strip()+' | uptime='+ (root/'uptime.txt').read_text(errors='replace').strip()+' | '+', '.join(x['mode']+'/'+x['request']+'='+x['status']+':'+str(x['seconds'])+'s' for x in result['probes'])+' | boot='+result['boot']+' | aned='+result['commands']['aned-errors']['status']+':'+str(result['aned_error_fault_lines'])+' | '+verdict
    (root/'INBOX-LINE.txt').write_text(summary+'\n');(root/'result.json').write_text(json.dumps(result,indent=2)+'\n')
    # Evidence-only archive. No application source, preferences or rollback pointer is changed.
    saved=pathlib.Path.home()/'Downloads'/'gor-bbu'/('vision-e1-'+stamp)
    saved.mkdir(parents=True,exist_ok=False);os.chmod(saved,0o700)
    (saved/'changes.txt').write_text('No application files changed. Evidence-only E1 probe.\n')
    archive=saved/'gor-vision-e1.zip'
    with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED) as z:
        for file in sorted(root.iterdir()):
            if file.name!='probe' and file.is_file():z.write(file,'gor-vision-e1/'+file.name)
    shutil.copy2(root/'INBOX-LINE.txt',saved/'INBOX-LINE.txt')
    print(summary);print('E1 evidence ZIP collected:',archive)
    for name in ['boot.txt','softwareupdate-history.txt','aned-errors.txt','default-rectangles.txt','default-landmarks.txt','cpu-rectangles.txt','cpu-landmarks.txt']:
        item=root/name
        if item.exists():
            print('E1 receipt '+name+' BEGIN')
            print(item.read_text(errors='replace')[-65536:])
            print('E1 receipt '+name+' END')
    print('No daemon restart or sudo was run. No application file was changed.')
    return 0

if __name__=='__main__':raise SystemExit(main())
